(()=>{'use strict';const C=window.CBL,$=C.$,$$=C.$$;
C.register('binary',el=>C.bitsLab(el,[128,64,32,16,8,4,2,1]));
C.register('hexadecimal',el=>C.bitsLab(el,[8,4,2,1],'hex'));
C.register('data-size',el=>{el.innerHTML=`<div class="lab"><div class="lab-help">値と単位を変えて、byteに直すとどれくらいになるか見ます。</div><div class="form-grid two"><div class="field"><label>値</label><input data-v type="number" min="0" value="1"></div><div class="field"><label>単位</label><select data-u><option>B</option><option>KB</option><option>MB</option><option>GB</option></select></div></div><div class="result"><small>10進接頭辞でbyte換算</small><strong data-r>1</strong><span class="subresult">byte</span></div><div class="interpret" data-i></div></div>`;const run=()=>{const v=Math.max(0,+$('[data-v]',el).value||0),u=$('[data-u]',el).value,i=['B','KB','MB','GB'].indexOf(u),b=v*1000**i;$('[data-r]',el).textContent=b.toLocaleString();$('[data-i]',el).innerHTML=`<strong>読み取れること:</strong> ${v} ${u} は ${b.toLocaleString()} byte。単位が1段上がると桁が大きく増えます。`};$('[data-v]',el).oninput=run;$('[data-u]',el).onchange=run;run()});
C.register('text-encoding',el=>{el.innerHTML=`<div class="lab"><div class="lab-help">A・あ・😊などを入力してください。同じ「1文字」でもUTF-8のbyte数が違います。</div><div class="field"><label>文字</label><input data-t value="あ"></div><div class="codebox" data-o aria-live="polite"></div><div class="interpret"><strong>読み取れること:</strong> 文字にはUnicodeの番号があり、UTF-8では通信・保存用のbyte列になります。</div></div>`;const run=()=>{$('[data-o]',el).textContent=[...$('[data-t]',el).value].map(c=>{const bs=[...new TextEncoder().encode(c)];return `${c}  →  U+${c.codePointAt(0).toString(16).toUpperCase()}  →  ${bs.map(b=>b.toString(16).padStart(2,'0').toUpperCase()).join(' ')}  (${bs.length} byte)`}).join('\n')||'文字を入力してください'};$('[data-t]',el).oninput=run;run()});
C.register('bitwise',el=>{el.innerHTML=`<div class="lab"><div class="lab-help">AND / OR / XORを切り替え、AとBを0/1にして結果を予想してから押してください。</div><div class="mode-tabs"><button class="btn active" data-op="AND">AND</button><button class="btn" data-op="OR">OR</button><button class="btn" data-op="XOR">XOR</button></div><div class="form-grid two"><button class="btn" data-a>A = 0</button><button class="btn" data-b>B = 0</button></div><div class="result"><small>出力</small><strong data-o>0</strong></div><div class="interpret" data-i></div></div>`;let a=0,b=0,op='AND';const run=()=>{const o=op==='AND'?(a&b):op==='OR'?(a|b):(a^b);$('[data-a]',el).textContent='A = '+a;$('[data-b]',el).textContent='B = '+b;$('[data-o]',el).textContent=o;$('[data-i]',el).innerHTML=`<strong>ルール:</strong> ${op==='AND'?'両方1のときだけ1。':op==='OR'?'どちらかが1なら1。':'2つが違うとき1。'}`};$('[data-a]',el).onclick=()=>{a^=1;run()};$('[data-b]',el).onclick=()=>{b^=1;run()};$$('[data-op]',el).forEach(x=>x.onclick=()=>{op=x.dataset.op;$$('[data-op]',el).forEach(y=>y.classList.toggle('active',x===y));run()});run()});
C.register('ip-address',el=>{const vals=[192,168,1,10];el.innerHTML=`<div class="lab"><div class="lab-help">4つの数字の − / ＋ を押してください。数字の裏側の8 bitが変わります。</div><div class="form-grid two">${vals.map((v,i)=>`<div class="field"><label>第${i+1}オクテット</label><div class="stepper"><button type="button" data-minus="${i}" aria-label="第${i+1}オクテットを1減らす">−</button><input data-o="${i}" type="number" min="0" max="255" value="${v}"><button type="button" data-plus="${i}" aria-label="第${i+1}オクテットを1増やす">＋</button></div></div>`).join('')}</div><div class="codebox" data-r></div><div class="interpret" data-i></div></div>`;const run=()=>{const a=$$('[data-o]',el).map(x=>Math.max(0,Math.min(255,+x.value||0)));$('[data-r]',el).textContent=a.join('.')+'\n'+a.map(n=>n.toString(2).padStart(8,'0')).join(' . ');$('[data-i]',el).innerHTML='<strong>読み取れること:</strong> IPv4は0〜255の数字が4つに見えますが、内部では8 bitが4組、合計32 bitです。'};$$('[data-minus]',el).forEach(b=>b.onclick=()=>{const x=$(`[data-o="${b.dataset.minus}"]`,el);x.value=Math.max(0,+x.value-1);run()});$$('[data-plus]',el).forEach(b=>b.onclick=()=>{const x=$(`[data-o="${b.dataset.plus}"]`,el);x.value=Math.min(255,+x.value+1);run()});$$('[data-o]',el).forEach(x=>x.oninput=run);run()});
C.register('cidr',el=>{el.innerHTML=`<div class="lab"><div class="lab-help">スライダーを /24 の前後へ動かしてください。「どこまでがネットワーク側か」という境界が変わります。</div><div class="field"><label>CIDR <strong data-c>/24</strong></label><input data-r type="range" min="0" max="32" value="24" style="width:100%"></div><div class="codebox" data-o></div><div class="interpret" data-i></div></div>`;const run=()=>{const c=+$('[data-r]',el).value,m=[];for(let i=0;i<4;i++){const u=Math.max(0,Math.min(8,c-i*8));m.push(u?256-2**(8-u):0)}$('[data-c]',el).textContent='/'+c;$('[data-o]',el).textContent=`ネットワーク部 ${c} bit | ホスト部 ${32-c} bit\nサブネットマスク ${m.join('.')}`;$('[data-i]',el).innerHTML=`<strong>読み取れること:</strong> /${c} は左から ${c} bit をネットワーク部として扱う境界です。`};$('[data-r]',el).oninput=run;run()});
C.register('port-number',el=>{const defs=[['SSH',22,'TCP'],['DNS',53,'UDP'],['HTTP',80,'TCP'],['HTTPS',443,'TCP']];el.innerHTML=`<div class="lab"><div class="lab-help">代表的なポートを押してください。IPが同じでも、ポートで届け先のサービスが変わります。</div><div class="lab-controls">${defs.map(x=>`<button type="button" class="btn" data-port="${x[1]}" data-service="${x[0]}" data-proto="${x[2]}">${x[0]} ${x[1]}</button>`).join('')}</div><div class="result"><small>宛先</small><strong style="font-size:24px" data-r>203.0.113.10:443</strong><span class="subresult" data-s>HTTPS / TCP</span></div><div class="interpret"><strong>読み取れること:</strong> IPが建物の住所なら、ポートは中の届け先番号のような役割です。</div></div>`;$$('[data-port]',el).forEach(b=>b.onclick=()=>{$('[data-r]',el).textContent='203.0.113.10:'+b.dataset.port;$('[data-s]',el).textContent=b.dataset.service+' / '+b.dataset.proto;$$('[data-port]',el).forEach(x=>x.classList.toggle('active',x===b))})});
C.register('http-methods',el=>{const defs={GET:['GET /users/42 HTTP/1.1','取得する','200 OK','通常は取得の意図。safe / idempotent。'],POST:['POST /users HTTP/1.1\nContent-Type: application/json\n\n{"name":"Aki"}','処理を依頼する','201 Created','POSTは同じ要求を繰り返すと同じ効果になるとは限りません。'],PUT:['PUT /users/42 HTTP/1.1\n\n{"name":"Aki"}','指定先を作成・置換する','200 OK','PUTは仕様上idempotent。'],DELETE:['DELETE /users/42 HTTP/1.1','指定先との関連付けを削除する','204 No Content','DELETEも仕様上idempotent。']};el.innerHTML=`<div class="lab"><div class="lab-help">GET / POST / PUT / DELETEを押し、リクエスト行と「意図」がどう変わるか比べます。</div><div class="lab-controls">${Object.keys(defs).map((m,i)=>`<button class="btn ${i?'':'active'}" data-m="${m}">${m}</button>`).join('')}</div><div class="codebox" data-r></div><div class="result"><small>Requestの意図</small><strong style="font-size:21px" data-a></strong><span class="subresult" data-s></span></div><div class="interpret" data-i></div></div>`;const run=m=>{const d=defs[m];$('[data-r]',el).textContent=d[0];$('[data-a]',el).textContent=d[1];$('[data-s]',el).textContent='例: '+d[2];$('[data-i]',el).innerHTML='<strong>読み取れること:</strong> '+d[3]};$$('[data-m]',el).forEach(b=>b.onclick=()=>{$$('[data-m]',el).forEach(x=>x.classList.toggle('active',x===b));run(b.dataset.m)});run('GET')});
C.register('http-status',el=>{const defs={200:['OK','要求が成功した。','画面やデータを通常どおり扱う'],301:['Moved Permanently','別URLへ恒久的に移動した。','Locationを見て新しいURLへ移動'],304:['Not Modified','キャッシュ済み表現を再利用できる。','保存済みデータを使う'],400:['Bad Request','要求の形式などに問題がある。','要求内容を見直す'],401:['Unauthorized','認証情報が必要・不十分。','認証を行う'],403:['Forbidden','サーバーは要求を理解したが許可しない。','権限を確認'],404:['Not Found','対象のリソースが見つからない。','URL等を確認'],429:['Too Many Requests','一定時間に要求が多すぎる。','待って再試行'],500:['Internal Server Error','サーバー側で予期しない問題。','サーバー側を調査'],503:['Service Unavailable','一時的に処理できない。','時間を置く・復旧を待つ']};el.innerHTML=`<div class="lab"><div class="lab-help">コードを押して、「数字」ではなく次にどう動くかを見ます。</div><div class="lab-controls">${Object.keys(defs).map((x,i)=>`<button class="btn ${i?'':'active'}" data-s="${x}">${x}</button>`).join('')}</div><div class="result"><small>HTTP Status</small><strong data-r>200</strong><span class="subresult" data-name></span></div><div class="interpret" data-i></div></div>`;const run=x=>{const d=defs[x];$('[data-r]',el).textContent=x;$('[data-name]',el).textContent=d[0];$('[data-i]',el).innerHTML=`<strong>意味:</strong> ${d[1]} <strong>次の動き:</strong> ${d[2]}`};$$('[data-s]',el).forEach(b=>b.onclick=()=>{$$('[data-s]',el).forEach(x=>x.classList.toggle('active',x===b));run(b.dataset.s)});run('200')});
})();